      "poi_id": "p22",
      "kind": "meal",
      "must_do_id": "m2",
      "note": "From what Tokek knows so far, this one stays because the crew asked for it, and the good bánh căn in this area is worth lingering over."
    },
    {
      "poi_id": "p123",
      "kind": "meal",
      "must_do_id": null,
      "note": "From what Tokek knows so far, dinner moves to a nearby area so the day keeps one gentle rhythm and nobody rushes a hot pot."
    }
  ]
